INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('gym-2037-11-14', '{"title":"🏋️ אימון השבוע השני — מוצ״ש Gold’s Gym Omori","why":"Now the only workout of the second week."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d3-02', '{"title":"Narita Express → Tokyo","why":"Since the lunch moved to Tokyo Station (see ''d3-04''). The Narita Express stops at Tokyo Station before Shinagawa, and T''s Tantan is inside the JR gates there (GRANSTA, Keiyo Street, 10:00–22:00), so lunch moves before the check-in instead of a trip back after it.","note":"לקנות כרטיס לאחר הנחיתה, לאחר ביקורת דרכונים ומזוודות. אין עדיין כרטיס רכבת לשדה. אין לקבוע יציאה מדויקת מראש. הכי פשוט: כרטיס N’EX עד Tokyo (הרכבת עוצרת שם לפני Shinagawa), ארוחה ב־T’s Tantan בתוך התחנה, ומשם JR (Yamanote או Keihin-Tohoku) ל־Shinagawa עם Suica, כ־10 דקות."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('to-disney-hotel', '{"title":"🧳 מעבר מלון: Shibuya → תחנת Tokyo → Shin-Urayasu","time":"16:30","why":"15.11: Omori → Tokyo Station → dinner → Keiyo Line → check-in, then laundry and an early night before Disney. 15.11 in the order it is lived: Tokyo Station dinner is on the way, before the Keiyo Line to Shin-Urayasu.","end":"17:00","note":"משיבויה לתחנת Tokyo ב־JR Yamanote, כ־25 דקות — המזוודות כבר בדרך ל־Oriental. אוכלות ב־T’s Tantan, ומאותה שדרה (Keiyo Street) קו Keiyo ל־Shin-Urayasu, כ־20 דקות. המלון ליד התחנה. שעות משוערות, לבדוק Google Maps בזמן אמת."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d3-04', '{"time":"15:30","why":"Lunch at Tokyo Station on the way from Narita, then check-in (see ''d3-04'').","note":"בדרך מהשדה, בלי המזוודות (נשלחו מנריטה עם SAGAWA): יורדות מה־N’EX בתחנת Tokyo. המסעדה בתוך שערי JR, ב־GRANSTA בשדרת Keiyo Street (בכיוון קו Keiyo), פתוחה בערך 10:00–22:00. 100% טבעוני לפי התכנון. אם בכל זאת המזוודות איתכן — המקום קטן, ויש בתוך השערים שמירת חפצים של GRANSTA ולוקרים. 3.11 הוא חג (יום התרבות), אז התחנה עמוסה. השעה תלויה בזמן היציאה מהשדה."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d3-03', '{"time":"17:00","note":"לינה 3–5 בנובמבר, שתי אורחות, חדר Twin. 17:00 כאן היא שעת הגעה משוערת בלבד, אחרי הארוחה בתחנת Tokyo. | שעות המלון: קבלת חדרים מ־15:00; פינוי חדר עד 11:00."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d15-04', '{"time":"17:00","note":"בתחנת Tokyo, בדרך לקו Keiyo — בתכנון בלבד. ביום ראשון סוגרים מוקדם יותר (בערך 21:00), אז ארוחה מוקדמת."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d15-05', '{"time":"18:30","note":"לינה 15–18 בנובמבר. צ׳ק־אין מ־15:00; 18:30 כאן שעת הגעה משוערת. | שעות המלון: קבלת חדרים מ־15:00; פינוי חדר עד 12:00. | המלון נמצא ב־Shin-Urayasu; אל תבלבלו עם מלון Disney רשמי במאיהמה. יש לו שאטל Partner Hotel לפארקים."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('shibuya-markets', '{"end":"16:15","why":"Without the trip back to Omori, the Shibuya shopping runs until the train to Tokyo Station."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d12-04', '{"note":"אושר לשתיכן — כל אחת הזמינה בנפרד, באותו חדר ובאותה שעה. טיפול 110 דקות כולל אבחון; כ־₪372.72 לכל אחת (שער 12.10). איחור של מעל 10 דקות עלול לקצר טיפול. תשלום בכרטיס בלבד.","why":"Each of us booked separately (the confirmation in Drive is Dana''s); same room, same time."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d6-03', '{"note":"שעה משוערת בלבד; יש לתאם עם זמני הדלקת נרות. הכביסה עברה לבוקר יום ראשון 8.11 — כביסה וייבוש לוקחים שעה וחצי עד שלוש שעות, וזה צפוף מדי לפני שבת.","why":"A full wash and dry takes 1.5–3 hours, too tight before candle lighting; see laundry.ts."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d5-01', '{"note":"צ׳ק־אאוט עד 11:00, רק עם התיק הקטן — המזוודות נשלחו לקובה ב־4.11. | שעות המלון: קבלת חדרים מ־15:00; פינוי חדר עד 11:00.","why":"The suitcases go ahead by Yamato on 4.11 (see luggage.ts), so 5.11 has no trip back to the hotel."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d5-02', '{"note":"להציץ בכמה חנויות Mandarake בתוך Nakano Broadway. שעות משתנות לפי חנות; הגעה סביב 12:00 הגיונית. בלי מזוודות — מכאן ישר לשינקנסן: לצאת עד 16:10."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d11-01', '{"note":"צ׳ק־אאוט עד 11:00, רק עם התיק הקטן — המזוודות נשלחו לאומורי ב־10.11."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('d15-02', '{"note":"Shibuya Sky לא הוזמן לפי האישורים שנמסרו. אפשר במקום זה קניות / שווקים באזור, בלי להתחייב לכרטיס נוסף. המזוודות כבר נשלחו ל־Oriental, אז אין צורך לחזור לאומורי."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('gym-2037-11-12', '{"removed":true,"why":"Morning workout before the long Shibuya + spa day; the late arrival the night before makes it too tight."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('bags-shinagawa', '{"removed":true,"why":"We always send the suitcases ahead (decided 15.10.2026; see luggage.ts), so nobody goes back for them."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO event_changes (key, data, updated_at, updated_by) VALUES ('omori-luggage', '{"removed":true,"why":"We always send the suitcases ahead (decided 15.10.2026; see luggage.ts), so nobody goes back for them."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO day_changes (key, data, updated_at, updated_by) VALUES ('2037-11-05', '{"route":"בוקר: צ׳ק־אאוט מ־Shinagawa Prince עם תיק קטן (המזוודות נשלחו לקובה ב־4.11) → Nakano Broadway ומנגה/אספנות → מ־Nakano ישר לתחנת Shinagawa, NOZOMI 53 ב־17:19 → Shin-Kobe 19:53 → CANDEO Kobe, שם מחכות המזוודות. להשאיר 30–45 דקות בתחנה לפני הרכבת."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO day_changes (key, data, updated_at, updated_by) VALUES ('2037-11-11', '{"route":"צ׳ק־אאוט ממלון אוסקה עם תיק קטן (המזוודות נשלחו לאומורי ב־10.11) → ארוחה / סיבוב בשינסאיבאשי → אם COPIC בעדיפות גבוהה: Tools Osaka Umeda בדרך צפונה, רק אם יש די זמן → לצאת לכיוון Shin-Osaka לכל המאוחר ב־17:00 → NOZOMI 46 ב־18:30 → Shinagawa ב־20:49 → נסיעה מקומית אל MYSTAYS PREMIER Omori."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO day_changes (key, data, updated_at, updated_by) VALUES ('2037-11-15', '{"route":"בוקר: צ׳ק־אאוט ב־MYSTAYS Omori ושליחת המזוודות ב־Yamato ל־Oriental Hotel → Shibuya Sky (אם תזמינו) + שווקים וקניות בשיבויה / Ebisu → JR לתחנת Tokyo וארוחה ב־T’s Tantan → קו Keiyo ל־Shin-Urayasu → צ׳ק־אין ב־Oriental Hotel Tokyo Bay וכביסה. זה יום מעבר מלון נפרד, לפני דיסנילנד ב־16.11."}', '2037-10-15T13:19:27.172Z', 'seed');
INSERT INTO day_changes (key, data, updated_at, updated_by) VALUES ('2037-11-03', '{"route":"נריטה T1 → Narita Express עד תחנת Tokyo (לקנות במקום) → ארוחה ב־T’s Tantan בתוך התחנה, עם המזוודות → JR ל־Shinagawa → צ׳ק־אין במלון → ארוחת ערב וקניות קלות. המסעדות הן הצעות גמישות ולא הזמנות."}', '2037-10-15T13:19:27.172Z', 'seed');
